package com.autojobapply.tracking; import java.nio.file.*; import java.sql.*;
public final class ApplicationQueueMigrationTest { public static void main(String[] a)throws Exception{Path p=Files.createTempFile("queue-legacy",".db");try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+p)){try(Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE application_queue (identity TEXT PRIMARY KEY, priority INTEGER NOT NULL, state TEXT NOT NULL, queued_at TEXT NOT NULL, updated_at TEXT NOT NULL)");s.executeUpdate("INSERT INTO application_queue VALUES('old',1,'SUBMITTED','a','b')");}}try(ApplicationTracker t=new ApplicationTracker(p)){t.initialize();t.initialize();}try(Connection c=DriverManager.getConnection("jdbc:sqlite:"+p);Statement s=c.createStatement()){try(ResultSet r=s.executeQuery("PRAGMA table_info(application_queue)")){boolean token=false,id=false,url=false;while(r.next()){token|="board_token".equals(r.getString("name"));id|="greenhouse_job_id".equals(r.getString("name"));url|="application_url".equals(r.getString("name"));}if(!(token&&id&&url))throw new AssertionError("columns");}try(ResultSet r=s.executeQuery("SELECT state FROM application_queue WHERE identity='old'")){if(!r.next()||!"SUBMITTED".equals(r.getString(1)))throw new AssertionError("history");}try(ResultSet r=s.executeQuery("SELECT name FROM sqlite_master WHERE type='index' AND name='uq_queue_greenhouse'")){if(!r.next())throw new AssertionError("index");}}Files.deleteIfExists(p);System.out.println("APPLICATION_QUEUE_MIGRATION_TEST_PASSED");}}
